public List<PageInfo> getScannedPages(SQLiteDatabase db, long documentId) {
    List<PageInfo> pages = new ArrayList<>();
    Cursor cursor = db.rawQuery(
            "SELECT page_number, file_path FROM scanned_pages WHERE document_id=? ORDER BY page_number",
            new String[]{String.valueOf(documentId)});
    if (cursor.moveToFirst()) {
        do {
            pages.add(new PageInfo(cursor.getInt(0), cursor.getString(1)));
        } while (cursor.moveToNext());
    }
    return pages;
}

