public int countCompletedWorkouts(SQLiteDatabase db, long userId) {
    int count = 0;
    Cursor cursor = db.query(
            "workouts",
            new String[]{"id"},
            "user_id=? AND completed=1",
            new String[]{String.valueOf(userId)},
            null,
            null,
            null);
    if (cursor != null && cursor.moveToFirst()) {
        do {
            count++;
        } while (cursor.moveToNext());
    }
    return count;
}

