public List<PointOfInterest> findNearbyPlaces(SQLiteDatabase db, double lat, double lng) {
    List<PointOfInterest> list = new ArrayList<>();
    Cursor cursor = db.rawQuery(
            "SELECT id, name, category FROM places WHERE lat BETWEEN ? AND ? AND lng BETWEEN ? AND ?",
            new String[]{String.valueOf(lat - 0.01), String.valueOf(lat + 0.01), String.valueOf(lng - 0.01), String.valueOf(lng + 0.01)});
    if (cursor != null) {
        do {
            if (!cursor.moveToFirst()) break;
            list.add(new PointOfInterest(cursor.getLong(0), cursor.getString(1), cursor.getString(2)));
        } while (cursor.moveToNext());
    }
    return list;
}

