public void fetchAlbumArt(String albumId) {
  String url = API_BASE + "/albums/" + albumId + "/art";
  try {
    URI uri = new URI(url);
    HttpGet get = new HttpGet(uri);
    AndroidHttpClient client = AndroidHttpClient.newInstance("MusicApp/1.0");
    HttpResponse response = client.execute(get);
    HttpEntity entity = response.getEntity();
    Bitmap cover = BitmapFactory.decodeStream(entity.getContent());
    mAlbumArtView.setImageBitmap(cover);
  } catch (Exception e) {
    Log.e(TAG, e.toString());
  }
}

public void fetchAlbumArt(String albumId) {
  String url = API_BASE + "/albums/" + albumId + "/art";
  AndroidHttpClient client = null;
  try {
    URI uri = new URI(url);
    HttpGet get = new HttpGet(uri);
    client = AndroidHttpClient.newInstance("MusicApp/1.0");
    HttpResponse response = client.execute(get);
    HttpEntity entity = response.getEntity();
    Bitmap cover = BitmapFactory.decodeStream(entity.getContent());
    mAlbumArtView.setImageBitmap(cover);
  } catch (Exception e) {
    Log.e(TAG, e.toString());
  } finally {
    if (client != null) {
      client.close();
    }
  }
}

public void uploadScan(byte[] pdfData) {
  try {
    HttpPost post = new HttpPost(SERVER_URL + "/upload");
    post.setEntity(new ByteArrayEntity(pdfData));
    AndroidHttpClient client = AndroidHttpClient.newInstance("DocScanner/2.0");
    HttpResponse response = client.execute(post);
    int code = response.getStatusLine().getStatusCode();
    if (code == 200) {
      Log.i(TAG, "Upload concluído");
    }
  } catch (Exception e) {
    Log.e(TAG, e.getMessage());
  }
}

