public void startPlayback(final Context context, final Uri trackUri) {
    PowerManager pm = (PowerManager) context.getSystemService(Context.POWER_SERVICE);
    WakeLock wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "MusicPlayer:Playback");
    wakeLock.setReferenceCounted(false);
    wakeLock.acquire(10 * 60 * 1000L);

    mediaPlayer.setDataSource(context, trackUri);
    mediaPlayer.prepareAsync();
    mediaPlayer.setOnPreparedListener(new MediaPlayer.OnPreparedListener() {
        @Override
        public void onPrepared(MediaPlayer mp) {
            mp.start();
        }
    });
}

public void startPlayback(final Context context, final Uri trackUri) {
    PowerManager pm = (PowerManager) context.getSystemService(Context.POWER_SERVICE);
    final WakeLock wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "MusicPlayer:Playback");
    wakeLock.setReferenceCounted(false);
    wakeLock.acquire(10 * 60 * 1000L);

    mediaPlayer.setDataSource(context, trackUri);
    mediaPlayer.prepareAsync();
    mediaPlayer.setOnPreparedListener(new MediaPlayer.OnPreparedListener() {
        @Override
        public void onPrepared(MediaPlayer mp) {
            try {
                mp.start();
            } finally {
                if (wakeLock.isHeld()) {
                    wakeLock.release();
                }
            }
        }
    });
}

public void scanDocument(final Context context, final File imageFile) {
    PowerManager pm = (PowerManager) context.getSystemService(Context.POWER_SERVICE);
    WakeLock wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "Scanner:OCR");
    wakeLock.setReferenceCounted(false);
    wakeLock.acquire(5 * 60 * 1000L);

    executor.execute(new Runnable() {
        @Override
        public void run() {
            ocrEngine.process(imageFile);
            callback.onScanFinished();
        }
    });
}

public void scanDocument(final Context context, final File imageFile) {
    PowerManager pm = (PowerManager) context.getSystemService(Context.POWER_SERVICE);
    final WakeLock wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "Scanner:OCR");
    wakeLock.setReferenceCounted(false);
    wakeLock.acquire(5 * 60 * 1000L);

    executor.execute(new Runnable() {
        @Override
        public void run() {
            try {
                ocrEngine.process(imageFile);
                callback.onScanFinished();
            } finally {
                if (wakeLock.isHeld()) {
                    wakeLock.release();
                }
            }
        }
    });
}

public void startWorkoutSession(final Context context, final WorkoutPlan plan) {
    PowerManager pm = (PowerManager) context.getSystemService(Context.POWER_SERVICE);
    WakeLock wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "Fitness:WorkoutSession");
    wakeLock.setReferenceCounted(false);
    wakeLock.acquire();

    timer.start(plan.getDurationMillis(), new TimerCallback() {
        @Override
        public void onTick(long remaining) {
            workoutListener.onProgress(remaining);
        }

        @Override
        public void onFinish() {
            workoutListener.onWorkoutCompleted();
        }
    });
}

