import android.app.IntentService;
import android.content.Intent;
import android.os.PowerManager;

public class FleetTelemetryService extends IntentService {
    private PowerManager.WakeLock telemetryLock;

    public FleetTelemetryService() {
        super("FleetTelemetryService");
    }

    @Override
    protected void onHandleIntent(Intent intent) {
        PowerManager pm = (PowerManager) getSystemService(POWER_SERVICE);
        telemetryLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "FleetApp:TelemetryLock");
        try {
            if (telemetryLock != null && !telemetryLock.isHeld()) {
                telemetryLock.acquire();
            }
            // processamento de telemetria
        } finally {
            if (telemetryLock != null && telemetryLock.isHeld()) {
                telemetryLock.release();
            }
        }
    }
}

