import android.app.Activity;
import android.os.Bundle;
import android.os.PowerManager;

public class FlightControlActivity extends Activity {
    private PowerManager.WakeLock flightLock;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        PowerManager pm = (PowerManager) getSystemService(POWER_SERVICE);
        flightLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "DroneApp:FlightLock");
    }

    @Override
    protected void onResume() {
        super.onResume();
        if (flightLock != null && !flightLock.isHeld()) {
            flightLock.acquire();
        }
    }

    @Override
    protected void onPause() {
        super.onPause();
        if (flightLock != null && flightLock.isHeld()) {
            flightLock.release();
        }
    }
}

