import android.app.Activity;
import android.os.Bundle;
import android.os.PowerManager;

public class PaymentProcessingActivity extends Activity {
    private PowerManager.WakeLock paymentLock;

    @Override
    protected void onResume() {
        super.onResume();
        PowerManager pm = (PowerManager) getSystemService(POWER_SERVICE);
        paymentLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "PayApp:PaymentLock");
        if (paymentLock != null && !paymentLock.isHeld()) {
            paymentLock.acquire();
        }
    }

    @Override
    protected void onStop() {
        super.onStop();
        if (paymentLock != null && paymentLock.isHeld()) {
            paymentLock.release();
        }
    }
}

