import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

public class PlaylistStore {

    public static Playlist loadLastPlaylist(String path) {
        try {
            ObjectInputStream obj = new ObjectInputStream(new FileInputStream(path));
            Object raw = obj.readObject();
            if (raw instanceof Playlist) {
                return (Playlist) raw;
            }
        } catch (Exception e) {
            Log.e(TAG, "Could not load playlist", e);
        }
        return null;
    }

    public static void saveLastPlaylist(Playlist playlist, String path) {
        try {
            ObjectOutputStream os = new ObjectOutputStream(new FileOutputStream(path));
            os.writeObject(playlist);
        } catch (Exception e) {
            Log.e(TAG, "Could not save playlist", e);
        }
    }
}

import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

public class PlaylistStore {

    public static Playlist loadLastPlaylist(String path) {
        ObjectInputStream obj = null;
        try {
            obj = new ObjectInputStream(new FileInputStream(path));
            Object raw = obj.readObject();
            if (raw instanceof Playlist) {
                return (Playlist) raw;
            }
        } catch (Exception e) {
            Log.e(TAG, "Could not load playlist", e);
        } finally {
            if (obj != null) {
                try {
                    obj.close();
                } catch (IOException e) {
                    Log.e(TAG, "Could not close playlist input stream", e);
                }
            }
        }
        return null;
    }

    public static void saveLastPlaylist(Playlist playlist, String path) {
        ObjectOutputStream os = null;
        try {
            os = new ObjectOutputStream(new FileOutputStream(path));
            os.writeObject(playlist);
        } catch (Exception e) {
            Log.e(TAG, "Could not save playlist", e);
        } finally {
            if (os != null) {
                try {
                    os.close();
                } catch (IOException e) {
                    Log.e(TAG, "Could not close playlist output stream", e);
                }
            }
        }
    }
}

