    formatter.close();
}

private void appendScanResult(final StringBuilder report, final Document doc) {
    final Formatter formatter = new Formatter(report);
    formatter.format("Page %d: %s\n", doc.getPageCount(), doc.getFileName());
    formatter.format("Resolution: %dx%d\n", doc.getWidth(), doc.getHeight());
    if (doc.isEncrypted()) {
        report.append("Encrypted document\n");
    }
}

