private void buildWorkoutSummary(final StringBuilder summary, final Workout workout) {
    final Formatter formatter = new Formatter(summary);
    formatter.format("Workout: %s\n", workout.getName());
    formatter.format("Calories: %.1f\n", workout.getCaloriesBurned());
    formatter.format("Duration: %d min\n", workout.getDurationMinutes());
    if (workout.isPersonalRecord()) {
        summary.append("New PR!\n");
    }
}

